import Image from "next/image";

/**
 * Museum Artifact Explorer — the project's own ER diagram, generated by
 * a script. Shown as a plate.
 */
export function Plate({ compact = false }: { compact?: boolean }) {
  return (
    <figure className={`plate ${compact ? "plate--compact" : ""}`} data-reveal>
      <a href="/evidence/museum-er.webp" target="_blank" rel="noreferrer" className="plate__frame" aria-label="Open the full-size ER diagram in a new tab">
        <Image
          src="/evidence/museum-er.webp"
          alt="Entity-relationship diagram with eight tables: civilizations, categories, artifacts, curators, exhibitions, exhibition_artifacts, favorites and deleted_artifacts_log, joined by one-to-many and many-to-many relationships."
          width={2200}
          height={1513}
          sizes="(min-width: 1024px) 60vw, 100vw"
          loading="lazy"
        />
      </a>
      <figcaption>
        The project&apos;s own ER diagram. Its column types still use SQLite notation; the live schema uses PostgreSQL identity columns.
      </figcaption>
    </figure>
  );
}
